def normalize_text(text: str) -> str:
    if not text:
        return ""
    text = text.lower()
    
    # Pre-punctuation phrase replacements for multi-word or hyphenated clinical terms
    phrase_map = {
        "rdw-cv": "rdw",
        "rdw cv": "rdw",
        "red cell": "erythrocyte",
        "white cell": "leukocyte",
        "packed cell volume": "hematocrit",
        "pcv": "hematocrit",
        "whole blood": "blood",
        "vitamin d, 25 hydroxy": "25 hydroxyvitamin d3",
        "vitamin d 25 hydroxy": "25 hydroxyvitamin d3"
    }
    for k, v in phrase_map.items():
        # Use regex to only replace whole words
        text = re.sub(r'\b' + re.escape(k) + r'\b', v, text)
        
    # Remove punctuation except spaces
    text = re.sub(r'[^\w\s]', ' ', text)
    # Replace multiple spaces with single space
    text = re.sub(r'\s+', ' ', text).strip()
    
    # Abbreviation expansion map
    abbreviations = {
        "red cell": "erythrocyte",
        "white cell": "leukocyte",
        "pcv": "hematocrit",
        "packed cell volume": "hematocrit",
        "rdw-cv": "rdw",
        "eosinophils": "eosinophil",
        "neutrophils": "neutrophil",
        "lymphocytes": "lymphocyte",
        "monocytes": "monocyte",
        "basophils": "basophil",
        "reticulocytes": "reticulocyte",
        "erythrocytes": "erythrocyte",
        "leukocytes": "leukocyte",
        "s": "serum",
        "ser": "serum",
        "plas": "plasma",
        "urn": "urine",
        "tiss": "tissue",
        "bld": "blood",
        "vit": "vitamin",
        "fbs": "fasting blood sugar",
        "hba1c": "hemoglobin a1c",
        "rbc": "red blood cells",
        "wbc": "white blood cells",
        "plt": "platelets",
        "bun": "blood urea nitrogen",
        "crp": "c reactive protein",
        "esr": "erythrocyte sedimentation rate",
        "tg": "triglycerides",
        "ldl": "low density lipoprotein",
        "hdl": "high density lipoprotein",
        "tsh": "thyroid stimulating hormone",
        "ft3": "free triiodothyronine",
        "ft4": "free thyroxine",
        "ast": "aspartate aminotransferase",
        "alt": "alanine aminotransferase",
        "sgot": "aspartate aminotransferase",
        "sgpt": "alanine aminotransferase",
        "alp": "alkaline phosphatase",
        "ggt": "gamma glutamyl transferase",
        "egfr": "estimated glomerular filtration rate",
        "cbc": "complete blood count",
        "pt": "prothrombin time",
        "inr": "international normalized ratio"
    }
    
    tokens = text.split()
    expanded_tokens = [abbreviations.get(token, token) for token in tokens]
    
    return " ".join(expanded_tokens)

def get_loinc_mapping(extracted_name: str) -> dict:
    """
    Performs a strict/lexical match of the extracted biomarker name against the dictionary using TF-IDF.
    Returns a dict with {"loinc_code": str, "name": str, "category": str} if a match is found.
    Otherwise returns None.
    """
    if not extracted_name:
        return None
        
    normalized_query = normalize_text(extracted_name)
    
    # 1. Exact Match first (fastest) on normalized strings
    for loinc, data in LOINC_DICTIONARY.items():
        syns_normalized = [normalize_text(s) for s in data["synonyms"]]
        if normalized_query in syns_normalized:
            return {
                "loinc_code": loinc,
                "name": data["name"],
                "category": data["category"]
            }
            
    # 2. TF-IDF + Cosine Similarity Match (Robust against stop-words)
    # The TF-IDF matrix is computed once at module initialization.
    query_vec = tfidf_vectorizer.transform([normalized_query])
    similarities = cosine_similarity(query_vec, tfidf_matrix).flatten()
    
    best_idx = similarities.argmax()
    best_score = similarities[best_idx]
    
    # Safe threshold for TF-IDF Cosine Similarity
    if best_score >= 0.55:
        best_match_loinc = tfidf_loinc_mapping[best_idx]
        return {
            "loinc_code": best_match_loinc,
            "name": LOINC_DICTIONARY[best_match_loinc]["name"],
            "category": LOINC_DICTIONARY[best_match_loinc]["category"]
        }
            
    return None

