# --- Pre-compute TF-IDF Matrix for Lexical Search ---
# This runs once on module initialization to enable ultra-fast semantic matching
_all_synonyms = []
tfidf_loinc_mapping = []

for loinc, data in LOINC_DICTIONARY.items():
    for syn in data["synonyms"]:
        _all_synonyms.append(normalize_text(syn))
        tfidf_loinc_mapping.append(loinc)

tfidf_vectorizer = TfidfVectorizer(analyzer='word', token_pattern=r'(?u)\b\w+\b')
tfidf_matrix = tfidf_vectorizer.fit_transform(_all_synonyms)

